import React, { useState, useEffect } from 'react';
import { Button } from 'primereact/button';
import { Tooltip } from 'primereact/tooltip';

/**
 * TextScaling Component
 * Provides WCAG-compliant text scaling controls for accessibility
 * 
 * Features:
 * - 8 scaling levels (75% to 200%)
 * - WCAG-compliant scaling up to 200%
 * - Persistent scaling across page reloads
 * - Keyboard accessible
 * - Screen reader friendly
 */
const TextScaling = ({ 
  className = '', 
  showLabels = false,
  size = 'xs-size',
  position = 'fixed'
}) => {
  const [currentScale, setCurrentScale] = useState(3); // Default to 100% (level 3)
  const [baseRootFs, setBaseRootFs] = useState(16);    // Baseline html font-size (px)
  
  // Scale levels (0-7)
  const scaleLevels = [
    { level: 1, percentage: 75, label: 'Very Small', factor: 0.75 },
    { level: 2, percentage: 87.5, label: 'Small', factor: 0.875 },
    { level: 3, percentage: 100, label: 'Normal', factor: 1.0 },
    { level: 4, percentage: 112.5, label: 'Large', factor: 1.125 },
    { level: 5, percentage: 125, label: 'Larger', factor: 1.25 },
    { level: 6, percentage: 150, label: 'Very Large', factor: 1.5 },
    { level: 7, percentage: 175, label: 'Extra Large', factor: 1.75 },
    { level: 8, percentage: 200, label: 'Maximum', factor: 2.0 }
  ];

  // Load saved scale on component mount
  useEffect(() => {
    // Enforce baseline: --uls-base-font-size = 14px and remove legacy --uls-global-scale
    document.documentElement.style.setProperty('--uls-base-font-size', '14px');
    document.documentElement.style.removeProperty('--uls-global-scale');
    const computedFs = 14;
    setBaseRootFs(14);

    const savedScale = localStorage.getItem('uls-text-scale');
    const level = savedScale ? parseInt(savedScale) : 3;
    setCurrentScale(level);
    applyScaling(level, computedFs);
  }, []);

  // Apply scaling by setting CSS var --uls-base-font-size (px)
  const applyScaling = (scaleLevel, base = baseRootFs) => {
    const factor = scaleLevels.find(s => s.level === scaleLevel)?.factor ?? 1;
    const newPx = Math.round(base * factor * 100) / 100;
    document.documentElement.style.setProperty('--uls-base-font-size', `${newPx}px`);
    // Ensure no conflicting inline font-size
    document.documentElement.style.removeProperty('font-size');
    localStorage.setItem('uls-text-scale', scaleLevel.toString());
  };

  // Handle scale change
  const handleScaleChange = (scaleLevel) => {
    setCurrentScale(scaleLevel);
    applyScaling(scaleLevel);
  };

  // Reset to default
  const handleReset = () => {
    handleScaleChange(3); // Reset to 100% (level 3)
  };

  // Get current scale info
  const currentScaleInfo = scaleLevels.find(scale => scale.level === currentScale);

  return (
    <div 
      className={`uls-text-scaling fixed fxb fcol column fvc gp3 align-center gap-4 pd8 bg-body bd2 rds3 shadow-md right-10 bottom-10  ${className}`}
    > 
      {/* Scale Up Button */}
      <Button
        icon="pi pi-plus"
        rounded text severity raised
        onClick={() => handleScaleChange(Math.min(8, currentScale + 1))}
        disabled={currentScale === 8}
        aria-label="Increase text size"
      />

      {/* Current Scale Display */}
      <div 
        style={{ 
          minWidth: '60px', 
          textAlign: 'center',
          fontSize: '12px',
          fontWeight: '500'
        }}
        aria-live="polite"
        aria-label={`Current text size: ${currentScaleInfo?.percentage}%`}
      >
        {showLabels ? currentScaleInfo?.label : `${currentScaleInfo?.percentage}%`}
      </div>
      
      {/* Scale Down Button */}
      <Button
        icon="pi pi-minus"
        rounded text severity raised
        onClick={() => handleScaleChange(Math.max(1, currentScale - 1))}
        disabled={currentScale === 1}
        aria-label="Decrease text size"
      />
      
      {/* Reset Button */}
      <Button
        icon="pi pi-refresh"
        rounded text severity raised 
        onClick={handleReset}
        aria-label="Reset text size to normal"
      />
      
      {/* Tooltips */}
      <Tooltip target="[data-pr-tooltip]" />
    </div>
  );
};

export default TextScaling;
